{
  "avaliacoes": [
    {
      "id": "E556a1e5525a2121b",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Na operação de instalações flutuantes, a estabilidade e seu controle são tratados como aspectos críticos; a documentação operacional deve indicar qual código ou critério é o caso limitante para estabilidade intacta e avariada.",
          "trechos": [
            "E556a1e5525a2121b:0:699",
            "E556a1e5525a2121b:699:1395"
          ],
          "condicoes": [
            "aplica-se a instalações flutuantes, incluindo monohull/surface units, semi-submersible e outras",
            "os códigos de referência podem variar conforme o projeto da instalação"
          ],
          "limites": [
            "a fonte cita códigos e prática regulatória do Reino Unido/HSE, não um requisito brasileiro",
            "o trecho não detalha valores operacionais nem critérios numéricos de aceitação"
          ]
        },
        {
          "proposicao": "O Marine Operations Manual reúne informações de estabilidade, carregamento e sistemas de lastro, e normalmente define limites de carga no convés e restrições de carregamento de tanques para evitar esforços estruturais excessivos e limitar efeitos de inundação.",
          "trechos": [
            "E556a1e5525a2121b:1395:2090"
          ],
          "condicoes": [
            "no contexto de instalações com documentação operacional e processo de aprovação/verificação",
            "os limites são definidos no manual da unidade"
          ],
          "limites": [
            "a fonte não fornece os limites específicos",
            "quando a instalação não é classificada, a aprovação esperada é por autoridade competente no processo de verificação, sem detalhar equivalentes fora daquela jurisdição"
          ]
        },
        {
          "proposicao": "Boa estabilidade intacta é descrita como a capacidade de a unidade retornar rapidamente à posição ereta após adernamento por vento ou ondas; perda de estabilidade é interpretada em associação a dano à integridade estanque do casco.",
          "trechos": [
            "E556a1e5525a2121b:1395:2090",
            "E556a1e5525a2121b:2090:2242"
          ],
          "condicoes": [
            "sob ação de vento e ondas",
            "na interpretação adotada pelo documento"
          ],
          "limites": [
            "trata-se de explicação técnica resumida, não de critério completo de projeto ou operação",
            "o trecho disponível termina sem desenvolver todas as consequências da perda de estabilidade"
          ]
        }
      ]
    },
    {
      "id": "E7939c73ca7bdc7c1",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "FPSO é apresentado como unidade flutuante estacionária de produção, armazenamento e escoamento de petróleo e gás, associada ao desenvolvimento de campos mais distantes da costa e em maiores lâminas d'água.",
          "trechos": [
            "E7939c73ca7bdc7c1:0:695"
          ],
          "condicoes": [
            "no contexto histórico e descritivo do uso de FPSOs em águas profundas"
          ],
          "limites": [
            "há números apagados no trecho, impedindo reconstrução temporal ou de vida útil",
            "como corpus concatenado sem fronteiras documentais claras, a rastreabilidade é limitada"
          ]
        },
        {
          "proposicao": "O FPSO pode apresentar limitações em condições ambientais severas, com movimentos significativos de roll e pitch, tornando o heave mais crítico do que em semi-submersíveis.",
          "trechos": [
            "E7939c73ca7bdc7c1:695:1385"
          ],
          "condicoes": [
            "em condições ambientais severas",
            "na comparação feita com plataformas semi-submersíveis"
          ],
          "limites": [
            "o trecho não quantifica severidade ambiental nem amplitudes admissíveis de movimento",
            "não é resultado experimental nem regra universal para todos os FPSOs"
          ]
        },
        {
          "proposicao": "Para FPSO, o sistema de ancoragem pode ser convencional/SPM ou turret; no turret, linhas de ancoragem e risers se concentram no mesmo local, permitindo rotação completa da unidade.",
          "trechos": [
            "E7939c73ca7bdc7c1:695:1385",
            "E7939c73ca7bdc7c1:1385:2081"
          ],
          "condicoes": [
            "na descrição dos arranjos de ancoragem do FPSO"
          ],
          "limites": [
            "o texto usa equivalência entre 'convencional' e SPM sem aprofundar variações conceituais",
            "não traz critérios de seleção entre arranjos nem impactos operacionais detalhados sobre poços e risers"
          ]
        }
      ]
    },
    {
      "id": "E81f378e923074656",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em instalações flutuantes de produção, especialmente FPSOs, condições marítimas adversas podem agitar os fluidos nos vasos separadores, perturbando a separação primária por remistura.",
          "trechos": [
            "E81f378e923074656:689:1380"
          ],
          "condicoes": [
            "principalmente em navios do tipo FPSO",
            "sob condições marítimas adversas"
          ],
          "limites": [
            "o trecho não quantifica o impacto nem define envelope operacional",
            "a explicação se refere ao processamento primário e não diretamente aos sistemas marítimos de estabilidade"
          ]
        },
        {
          "proposicao": "A agitação excessiva dos fluidos em separadores pode gerar alarmes incorretos de nível e pode ocasionar parada de produção por shutdown.",
          "trechos": [
            "E81f378e923074656:689:1380"
          ],
          "condicoes": [
            "quando há agitação excessiva dos fluidos no interior dos equipamentos de separação"
          ],
          "limites": [
            "o texto aponta possibilidade, não inevitabilidade",
            "não detalha a lógica de controle nem critérios de atuação dos alarmes"
          ]
        },
        {
          "proposicao": "Tecnologias ciclônicas são apresentadas como alternativa cujo desempenho de separação seria independente do movimento da embarcação, com potencial de minimizar perda de desempenho e descontrole de interface e reduzir parte da instrumentação de controle.",
          "trechos": [
            "E81f378e923074656:1380:2073"
          ],
          "condicoes": [
            "com emprego de novas tecnologias ciclônicas substituindo alguns vasos separadores"
          ],
          "limites": [
            "trata-se de expectativa/explicação técnica do texto, não de comprovação universal para qualquer instalação",
            "os valores numéricos de aceleração estão parcialmente apagados e não podem ser reconstruídos",
            "a eliminação de instrumentos é contextual e não deve ser generalizada"
          ]
        }
      ]
    },
    {
      "id": "E11483a0c65448a26",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Sistemas permanentes de amarração são descritos como desenvolvidos para garantir a estabilidade de estruturas flutuantes offshore.",
          "trechos": [
            "E11483a0c65448a26:0:695"
          ],
          "condicoes": [
            "no contexto de estruturas flutuantes em ambiente offshore"
          ],
          "limites": [
            "o trecho não distingue estabilidade global, posicionamento e integridade de forma detalhada",
            "por ser corpus concatenado, a independência documental é indeterminada"
          ]
        },
        {
          "proposicao": "Entre os sistemas de amarração citados estão single point mooring, turret, spread mooring e dynamic positioning; o spread mooring é associado a ambientes menos agressivos e o DP a unidades com grande deslocamento offset e pouco tempo de estadia.",
          "trechos": [
            "E11483a0c65448a26:0:695",
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "na classificação apresentada pela fonte",
            "DP podendo trabalhar em conjunto com outros sistemas de ancoragem"
          ],
          "limites": [
            "a fonte não estabelece critérios formais de seleção nem limites ambientais objetivos",
            "a associação a 'ambientes menos agressivos' e 'pouco tempo de estadia' é descritiva, não normativa"
          ]
        },
        {
          "proposicao": "A configuração convencional em catenária é descrita como tendo trecho apoiado no leito marinho e transmitindo apenas esforços horizontais à fundação, o que condiciona a compatibilidade com âncoras que não resistem a componentes verticais.",
          "trechos": [
            "E11483a0c65448a26:1384:2084",
            "E11483a0c65448a26:2084:2396"
          ],
          "condicoes": [
            "na configuração tipo convencional/catenária"
          ],
          "limites": [
            "há números apagados relativos a proporções e ângulos, impossibilitando reconstrução",
            "o trecho não compara desempenho completo com taut leg ou tendões verticais"
          ]
        }
      ]
    },
    {
      "id": "Ecef652bd9a854b94",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve FPSO como unidade marítima para produção, armazenamento e transferência de petróleo, composta por casco semelhante ao de navio e topside.",
          "trechos": [
            "Ecef652bd9a854b94:700:1398"
          ],
          "condicoes": [
            "na descrição geral do arranjo de FPSO"
          ],
          "limites": [
            "não detalha capacidades, taxas ou limites operacionais",
            "é descrição geral, não procedimento operacional"
          ]
        },
        {
          "proposicao": "O turret é apresentado como recurso para permitir que o navio gire e fique alinhado com condições ambientais extremas.",
          "trechos": [
            "Ecef652bd9a854b94:1398:2093"
          ],
          "condicoes": [
            "para evitar severas condições ambientais",
            "quando o FPSO emprega turret"
          ],
          "limites": [
            "o texto não informa critérios de acionamento, envelopes ambientais ou consequências para risers",
            "não implica que turret elimine todos os efeitos ambientais"
          ]
        },
        {
          "proposicao": "Entre as características atribuídas ao FPSO estão adequação a águas profundas e ultraprofundas, aproveitamento de superpetroleiros, flexibilidade de configuração entre campos e capacidade de armazenamento com escoamento por navios aliviadores; a completação dos poços é indicada como molhada.",
          "trechos": [
            "Ecef652bd9a854b94:1398:2093"
          ],
          "condicoes": [
            "na listagem de características apresentada pela fonte"
          ],
          "limites": [
            "são características gerais, não garantias para qualquer projeto",
            "o trecho não trata de compatibilidade detalhada com tipos de riser nem com sistemas de lastro"
          ]
        }
      ]
    },
    {
      "id": "Ecfd57b5e0b04f422",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A migração de plataformas fixas para sistemas flutuantes ancorados é explicada, entre outros motivos, pela inviabilidade econômica de aumentar excessivamente a rigidez estrutural em águas mais profundas para evitar amplificação dinâmica e possível ressonância.",
          "trechos": [
            "Ecfd57b5e0b04f422:699:1397",
            "Ecfd57b5e0b04f422:1397:2084"
          ],
          "condicoes": [
            "no avanço para lâminas d'água mais profundas",
            "quando a frequência natural se aproxima da excitação por ondas"
          ],
          "limites": [
            "há números apagados de profundidade e frequência",
            "a explicação é conceitual e não substitui análise estrutural específica"
          ]
        },
        {
          "proposicao": "As semi-submersíveis são descritas como estruturas flutuantes usadas para produção, completação e perfuração, com pontoons e colunas, tendo calado ajustável por bombeio de água para tanques de lastro.",
          "trechos": [
            "Ecfd57b5e0b04f422:1397:2084"
          ],
          "condicoes": [
            "na descrição da arquitetura e operação de lastro da semi-submersível"
          ],
          "limites": [
            "o trecho trata de semi-submersíveis, servindo como comparação contextual ao FPSO",
            "não fornece procedimentos de controle de lastro"
          ]
        },
        {
          "proposicao": "Navios FPSO são apresentados como unidades adaptadas para extrair, armazenar e exportar petróleo.",
          "trechos": [
            "Ecfd57b5e0b04f422:2084:2504"
          ],
          "condicoes": [
            "na descrição geral das plataformas para exploração e produção"
          ],
          "limites": [
            "o trecho disponível é breve e não cobre integração com ancoragem, poços, risers ou estabilidade",
            "a formulação usa 'adaptados', sem afirmar que todo FPSO decorra de conversão"
          ]
        }
      ]
    }
  ],
